import type { z } from 'zod';
import { SAUDI_ARABIC_SPEECH_GUIDE } from '../speech/saudi-arabic-speech.js';

type AgentSettings = Pick<
  z.infer<typeof AgentSettingsDraftRequestSchema>,
  'greeting' | 'instructionTemplate' | 'voice' | 'businessHours' | 'escalation'
>;

export type AgentVoice = AgentSettings['voice'];
export type AgentProfileSettings = AgentSettings;

export type AgentProfile = {
  locale: Locale;
  greeting: string;
  instructions: string;
  voice: AgentVoice;
};

